package tw.com.tft.documentscanner.model; import org.json.*; public class ScanItem { public String sourcePath; public float[] corners; public FilterMode filter=FilterMode.CLEAR; public boolean cropConfirmed=false; public String sourceType="GALLERY"; public ScanItem(String p){sourcePath=p;} public JSONObject toJson() throws JSONException{JSONObject o=new JSONObject();o.put("sourcePath",sourcePath);o.put("filter",filter.name());o.put("cropConfirmed",cropConfirmed);o.put("sourceType",sourceType);if(corners!=null){JSONArray a=new JSONArray();for(float v:corners)a.put((double)v);o.put("corners",a);}return o;} public static ScanItem fromJson(JSONObject o)throws JSONException{ScanItem i=new ScanItem(o.getString("sourcePath"));i.filter=FilterMode.valueOf(o.optString("filter",FilterMode.CLEAR.name()));i.cropConfirmed=o.optBoolean("cropConfirmed",false);i.sourceType=o.optString("sourceType","GALLERY");JSONArray a=o.optJSONArray("corners");if(a!=null&&a.length()==8){i.corners=new float[8];for(int x=0;x<8;x++)i.corners[x]=(float)a.getDouble(x);}return i;} }